+import { useEffect, useState } from "react";
+import { CheckCircle2, Loader2, Settings, X } from "lucide-react";
+import { updatePosterSettings } from "../services/ads";
+import type { AdResponse } from "../services/types";
+import { getUserErrorMessage } from "../utils/errorMessage";
+
+interface PosterSettingsModalProps {
+  isOpen: boolean;
+  onClose: () => void;
+  ad: AdResponse | null;
+  onSuccess: (updatedAd: AdResponse) => void;
+}
+
+export default function PosterSettingsModal({
+  isOpen,
+  onClose,
+  ad,
+  onSuccess,
+}: PosterSettingsModalProps) {
+  const [isPosterAllowed, setIsPosterAllowed] = useState(true);
+  const [showEmailOnPoster, setShowEmailOnPoster] = useState(true);
+  const [showPhoneOnPoster, setShowPhoneOnPoster] = useState(true);
+
+  const [submitting, setSubmitting] = useState(false);
+  const [error, setError] = useState<string | null>(null);
+  const [successMsg, setSuccessMsg] = useState<string | null>(null);
+
+  useEffect(() => {
+    if (isOpen && ad) {
+      setIsPosterAllowed(ad.isPosterAllowed ?? true);
+      setShowEmailOnPoster(ad.showEmailOnPoster ?? true);
+      setShowPhoneOnPoster(ad.showPhoneOnPoster ?? true);
+      setError(null);
+      setSuccessMsg(null);
+      setSubmitting(false);
+    }
+  }, [isOpen, ad]);
+
+  useEffect(() => {
+    if (!isOpen) return;
+
+    const handleKeyDown = (event: KeyboardEvent) => {
+      if (event.key === "Escape") {
+        onClose();
+      }
+    };
+
+    const previousOverflow = document.body.style.overflow;
+    document.body.style.overflow = "hidden";
+    window.addEventListener("keydown", handleKeyDown);
+
+    return () => {
+      document.body.style.overflow = previousOverflow;
+      window.removeEventListener("keydown", handleKeyDown);
+    };
+  }, [isOpen, onClose]);
+
+  if (!isOpen || !ad) return null;
+
+  const handleSubmit = async (e: React.FormEvent) => {
+    e.preventDefault();
+    setSubmitting(true);
+    setError(null);
+    setSuccessMsg(null);
+
+    const payload = {
+      isPosterAllowed,
+      showEmailOnPoster: isPosterAllowed ? showEmailOnPoster : false,
+      showPhoneOnPoster: isPosterAllowed ? showPhoneOnPoster : false,
+    };
+
+    try {
+      const updatedAd = await updatePosterSettings(ad.id, payload);
+      setSuccessMsg("Ayarlar başarıyla kaydedildi.");
+      
+      // Update state immediately without page reload (Optimistic UI)
+      onSuccess(updatedAd || { ...ad, ...payload });
+
+      setTimeout(() => {
+        onClose();
+      }, 1200);
+    } catch (err) {
+      console.error("Afiş ayarları kaydedilirken hata:", err);
+      setError(
+        getUserErrorMessage(
+          err,
+          "Afiş ayarları kaydedilirken bir hata oluştu.",
+        ),
+      );
+    } finally {
+      setSubmitting(false);
+    }
+  };
+
+  return (
+    <div
+      className="fixed inset-0 z-[200] flex items-center justify-center bg-slate-950/60 px-4 py-8 backdrop-blur-sm"
+      role="presentation"
+      onMouseDown={onClose}
+    >

