+function getListingStatus(adType: AdType): string {
+  switch (adType) {
+    case "LOST":
+      return "Kayıp";
+    case "FOUND":
+      return "Bulunan";
+    case "ADOPTION":
+      return "Sahiplendirme";
+    default:
+      return "İlan";
+  }
+}
+
+function getListingStatusClass(adType: AdType): string {
+  switch (adType) {
+    case "LOST":
+      return "lost";
+    case "FOUND":
+      return "found";
+    case "ADOPTION":
+      return "adoption";
+    default:
+      return "lost";
+  }
+}
+
+function getSpeciesLabel(species: AdResponse["species"]): string {
+  switch (species) {
+    case "CAT":
+      return "Kedi";
+    case "DOG":
+      return "Köpek";
+    default:
+      return species;
+  }
+}
+
+function getGenderLabel(gender: AdResponse["gender"]): string {
+  switch (gender) {
+    case "MALE":
+      return "Erkek";
+    case "FEMALE":
+      return "Dişi";
+    case "UNKNOWN":
+      return "Bilinmiyor";
+    default:
+      return gender;
+  }
+}
+
+function getAgeGroupLabel(ageGroup: AdResponse["ageGroup"]): string {
+  switch (ageGroup) {
+    case "BABY":
+      return "Yavru";
+    case "YOUNG":
+      return "Genç";
+    case "ADULT":
+      return "Yetişkin";
+    case "SENIOR":
+      return "Yaşlı";
+    default:
+      return ageGroup;
+  }
+}
+
+function formatDate(dateString: string): string {
+  const date = new Date(dateString);
+
+  if (Number.isNaN(date.getTime())) {
+    return "";
+  }
+
+  return new Intl.DateTimeFormat("tr-TR", {
+    day: "numeric",
+    month: "short",
+    year: "numeric",
+  }).format(date);
+}
+
+function getLocationLabel(ad: AdResponse): string {
+  if (
+    typeof ad.latitude === "number" &&
+    typeof ad.longitude === "number"
+  ) {
+    return `${ad.latitude.toFixed(4)}, ${ad.longitude.toFixed(4)}`;
+  }
+
+  return "Konum belirtilmemiş";
+}
